def carpan(n):
    def carp(x):
        return x * n
    return carp

uc_kat = carpan(3)
print(uc_kat(5))

def kaydet(f):
    def sarici(*args):
        print("çağrıldı:", f.__name__)
        return f(*args)
    return sarici

@kaydet
def topla(a, b):
    return a + b

print(topla(2, 3))

from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

print(fib(30))
